/**
 *
 * DataTableExport provides a trigger for exporting DataTable data.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableExport
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
export type DataTableExportPassThroughType<E> = PassThroughType<DataTableExportInstance, E>;
export interface DataTableExportPassThrough {
    root?: DataTableExportPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
}
export interface DataTableExportProps extends BaseComponentProps<DataTableExportInstance, unknown, DataTableExportPassThrough> {
    /**
     * Only export selected rows.
     */
    selectionOnly?: boolean;
    /**
     * Fields to export. If not provided, all fields from first row are used.
     */
    fields?: string[];
    /**
     * Column headers for export (maps field to header label).
     */
    headers?: Record<string, string>;
    /**
     * CSV separator character.
     * @default ','
     */
    separator?: string;
    /**
     * File name for download (without extension).
     * @default 'download'
     */
    fileName?: string;
}
export interface DataTableExportState {
}
export interface DataTableExportExposes {
    datatable: DataTableRootInstance | undefined | null;
}
export type DataTableExportInstance = ComponentInstance<DataTableExportProps, DataTableExportState, DataTableExportExposes>;
